/** Exact project tag -> glyph key. Tags without a brand glyph are absent. */
const TAG_ICONS: Record<string, keyof typeof ICONS> = {
  "Deno": "deno",
  "Deno KV": "deno",
  "Fresh 2": "fresh",
  "Preact": "preact",
  "SQLite": "sqlite",
  "Tailwind": "tailwindcss",
  "Python": "python",
  "Astro": "astro",
  "TinaCMS": "tina",
  "Cloudflare": "cloudflare",
  "Cloudflare Tunnel": "cloudflare",
  "GitHub Actions": "githubactions",
  "PHP": "php",
  "JavaScript": "javascript",
  "Moodle": "moodle",
  "TypeScript": "typescript",
  "PostgreSQL": "postgresql",
  "Svelte": "svelte",
  "Docker": "docker",
  "C++": "cplusplus",
  "jQuery": "jquery",
  "Git": "git",
  "Bitbucket": "bitbucket",
  "Jira": "jira",
  "Angular": "angular",
  "Google APIs": "google",
  "Microsoft Graph": "microsoft",
  "Linux": "linux",
  "Windows": "windows",
  "Raspberry Pi": "raspberrypi",
  "Ansible": "ansible",
  "WireGuard": "wireguard",
  "OpenVPN": "openvpn",
  "Gitea": "gitea",
  "SonarQube": "sonarqube",
  "Synology NAS": "synology",
  "OpenCode": "opencode",
  "DeepSeek Harness": "deepseek",
  "Bash": "bash",
  "ReScript": "rescript",
  "C#": "csharp",
  "Rust": "rust",
  "CSS": "css",
  "WordPress": "wordpress",
  "WooCommerce": "woocommerce",
  "MySQL": "mysql",
  "Unity": "unity",
  "Arduino": "arduino",
  "ESP32": "espressif",
  "DynamoDB": "amazondynamodb",
  "Azure Functions": "azurefunctions",
  "Ollama": "ollama",
  "MCP": "modelcontextprotocol",
  "Skills": "agentskills",
  "Pi": "pi",
  "Meta Quest": "meta",
};

/** Tones for stacks that have no official glyph, keyed by project tag. */
const TAG_COLORS: Record<string, string> = {
  "Java": "#E76F00",
  "PyInstaller": "#FFD166",
  "Oak": "#7ED0A8",
  "PostgREST": "#8AB4F8",
  "Active Directory": "#4C9AFF",
  "OpenGnsys": "#53B58B",
  "IMAP / POP / SMTP": "#D4A373",
  "NFS / SMB": "#8FA7C7",
  "Rsync": "#B07CC6",
  "Claude Code": "#E08D6E",
  "Gemini CLI": "#6EA8FF",
  "Gentle Shell": "#8FBF7F",
};

/** Brand tone for a tag, including stacks rendered as monograms. */
export function techColorForTag(tag: string): string {
  return techIconForTag(tag)?.color ?? TAG_COLORS[tag] ?? "#A7B3C6";
}

/** Resolve a project technology tag to its vendored brand glyph. */
export function techIconForTag(tag: string): TechIcon | undefined {
  const key = TAG_ICONS[tag];
  return key === undefined ? undefined : ICONS[key];
}
